    const snapshot = capture(); if (!snapshot) throw Error(t('请先加载数据，再更新视角'));
    bookmark.snapshot = snapshot; bookmark.updatedAt = new Date().toISOString(); pendingBookmarks.set(bookmark.id, bookmark); updateBookmarks();
