    this.target = [0, 0, 0];
    this.origin = [0, 0, 0];
    this.baseHeight = 10;
    this.bounds = null;
    this.buffers = {};
    this.models = [];
    this.activeClouds = [];
    this.pointCount = 0;
    this.edgeCount = 0;
    this.triangleCount = 0;
    this.count = 0;
    this.exportTarget = null;
    this.disposed = false;
